import type { DistanceTierFilter } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface DistanceTierEntry {
  label: string;
  variant: BadgeVariants;
}

export const distanceTierConfig: Record<DistanceTierFilter, DistanceTierEntry> = {
  local: { label: 'Local', variant: 'success' },
  qrf: { label: 'QRF', variant: 'info' },
  no_location: { label: 'No location', variant: 'default' },
};

export const distanceTierOptions: SelectItem<DistanceTierFilter>[] = Object.entries(distanceTierConfig).map(
  ([value, { label }]) => ({ name: label, value: value as DistanceTierFilter })
);
