<template>
  <section class="flex flex-col gap-6">
    <div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <h2 class="text-xl font-semibold">Recruitment</h2>
      <div class="flex flex-col gap-0.5 sm:items-end">
        <NuxtLink
          :to="{ name: 'recruitment-messages', query: { mentioned_project_ids: projectId } }"
          class="text-sm text-primary hover:underline"
        >
          View all messages{{ messageCount > 0 ? ` (${messageCount})` : '' }} →
        </NuxtLink>
        <span v-if="latestMessageAt" class="text-xs text-muted-foreground">
          Last activity {{ formatDistanceToNow(new Date(latestMessageAt)) }} ago
        </span>
      </div>
    </div>

    <Card class="p-4">
      <template v-if="isCampaignLoading">
        <AppLoader subject="campaign" variant="inline" />
      </template>
      <template v-else-if="campaign">
        <div class="flex items-center gap-3 text-sm flex-wrap">
          <LabeledEntityCampaign :campaign="{ id: campaign.id, name: campaign.name }" />
          <Badge v-if="campaign.paused_at" variant="warning">
            Paused{{ campaign.paused_reason ? `: ${getCampaignPauseReason(campaign.paused_reason).label}` : '' }}
          </Badge>
          <Badge v-else :variant="getCampaignUrgency(campaign.urgency_level).variant">
            {{ getCampaignUrgency(campaign.urgency_level).label }}
          </Badge>
          <NuxtLink
            :to="{ name: 'recruitment-campaigns-id-stats', params: { id: campaign.id } }"
            class="ml-auto text-primary hover:underline"
          >
            Campaign stats →
          </NuxtLink>
        </div>
        <div v-if="campaign.paused_at" class="text-xs text-warning-foreground mt-1">
          Paused {{ formatDistanceToNow(new Date(campaign.paused_at)) }} ago
        </div>
        <div class="border-t border-border pt-4 mt-4 grid grid-cols-1 sm:grid-cols-2 gap-4">
          <LabeledValue label="Channel Strategy" :value="getChannelStrategy(campaign.channel_strategy).label" />
          <LabeledValue
            label="Application Target"
            :value="`${campaign.applications_count ?? 0} / ${campaign.target_application_count ?? '—'}`"
          />
          <LabeledValue
            label="Assignment Target"
            :value="`${campaign.assignments_count ?? 0} / ${campaign.target_assignment_count ?? '—'}`"
          />
        </div>
      </template>
      <template v-else>
        <div class="flex items-start gap-3">
          <SparklesIcon class="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div class="flex-1">
            <h3 class="text-sm font-semibold text-foreground">No automatic campaign yet</h3>
            <p class="text-sm text-muted-foreground mt-1">
              An automatic campaign messages eligible canvassers hourly, respects daily caps, and pauses itself once the
              project is staffed. This is the recommended way to recruit for a project.
            </p>
            <div class="flex flex-wrap items-center gap-x-3 gap-y-2 mt-3">
              <NuxtLink :to="{ name: 'recruitment-campaigns-create', query: { project_id: projectId } }">
                <Button size="sm">Create Automatic Campaign</Button>
              </NuxtLink>
            </div>
          </div>
        </div>
      </template>
    </Card>

    <ProjectRecruitmentListFilters :params="params" />

    <FilterTabsNav v-if="data?.tier_counts" :items="tierTabs" rounded show-zero-count stretched />

    <Alert v-if="selection.count.value > 0" class="sticky top-4 z-10">
      <Mail class="mt-2.5" />
      <AlertTitle class="flex flex-wrap items-center justify-between min-h-9 gap-2">
        {{ selection.count.value }} / {{ MAX_SELECTION }} selected
        <div class="flex items-center gap-2">
          <Button size="sm" @click="isSendDialogOpen = true"> Send Batch Email </Button>
          <ResetCountersDialog
            v-if="isAdmin"
            mode="batch"
            :contacts="selection.selectedItems.value"
            @reset="selection.clear()"
          >
            <Button size="sm" variant="outline" :prepend-icon="RotateCcwIcon">Reset Counters</Button>
          </ResetCountersDialog>
          <Button variant="outline" size="sm" @click="selection.clear()"> Clear selection </Button>
        </div>
      </AlertTitle>
    </Alert>

    <!-- Outside the count-gated Alert on purpose: a partial send clears the selection, unmounting the
         Alert and its skip-reason list mid-render. -->
    <RecruitmentSendBatchDialog
      v-if="isDialogDataReady && defaultChannelStrategy"
      v-model="isSendDialogOpen"
      mode="project"
      :project-id="projectId"
      :selected-contacts="selection.selectedItems.value"
      :default-channel-strategy="defaultChannelStrategy"
      :default-strategy-source="defaultStrategySource"
      @sent="onSent"
    />

    <Card>
      <AppLoader v-if="isLoading" subject="eligible contacts" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load eligible contacts" variant="table" />
      <ResponsiveTable v-else rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead class="w-10">
            <Checkbox
              :model-value="pageSelectState"
              :disabled="selection.remainingCapacity.value === 0 && pageSelectState !== true"
              @update:model-value="() => selection.togglePage(selectableItems)"
            />
          </ResponsiveTableHead>
          <ResponsiveTableHead> Email </ResponsiveTableHead>
          <ResponsiveTableHead> Name </ResponsiveTableHead>
          <ResponsiveTableHead> Distance </ResponsiveTableHead>
          <ResponsiveTableHead> Readiness </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> General sent </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> Project sent </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableEmpty
            v-if="!data || data.items.length === 0"
            :colspan="7"
            :cols="4"
            :cols-sm="4"
            class="text-center"
          >
            <AppEmpty
              v-if="params.search_query"
              variant="table"
              :title="`No eligible contacts found for ${params.search_query}`"
              description="They may be suppressed, already applied, or assigned elsewhere."
            >
              <NuxtLink
                :to="{ name: 'staffing-resources', query: { search_query: params.search_query } }"
                class="text-sm text-primary hover:underline"
              >
                View in all staffing resources →
              </NuxtLink>
            </AppEmpty>
            <AppEmpty v-else variant="table" subject="eligible contacts" />
          </ResponsiveTableEmpty>
          <ResponsiveTableRow
            v-for="contact in data?.items"
            :key="contact.email"
            :to="{ name: 'staffing-resources-email', params: { email: contact.email } }"
          >
            <ResponsiveTableCell :cols="1" :cols-sm="1" @click.stop.prevent>
              <Checkbox
                :model-value="selection.isSelected(contact.email)"
                :disabled="!selection.isSelected(contact.email) && selection.remainingCapacity.value === 0"
                @update:model-value="
                  () =>
                    selection.toggle({
                      email: contact.email,
                      first_name: contact.first_name,
                      last_name: contact.last_name,
                    })
                "
              />
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Email">
              {{ contact.email }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Name">
              {{ formatContactName(contact.first_name, contact.last_name) }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Distance">
              <div class="flex items-center gap-1 whitespace-nowrap">
                <template v-if="contact.distance_classification">
                  <Badge :variant="getDistanceClassification(contact.distance_classification).variant">
                    {{ getDistanceClassification(contact.distance_classification).label }}
                  </Badge>
                  <span v-if="contact.distance_miles !== null" class="text-sm text-muted-foreground">
                    · {{ Math.round(contact.distance_miles) }} mi
                  </span>
                </template>
                <span v-else class="text-muted-foreground">No location</span>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Readiness">
              <div class="flex flex-wrap items-center gap-1">
                <Badge :variant="getReadinessStage(contact.readiness_stage).variant">
                  {{ getReadinessStage(contact.readiness_stage).label }}
                </Badge>
                <Badge v-if="exhaustionLabel(contact)" variant="destructive">
                  {{ exhaustionLabel(contact) }}
                </Badge>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="General sent">
              {{ contact.general_message_count }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="Project sent">
              {{ contact.project_message_count }}
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter
          v-if="!error && !isLoading && data && data.total_count > 0"
          :colspan="7"
          :cols="2"
          :cols-sm="2"
        >
          <AppPagination :page="params.page" :total="data.total_count" :size="params.size" label="contacts" />
        </ResponsiveTableFooter>
      </ResponsiveTable>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { Mail, RotateCcwIcon, SparklesIcon } from 'lucide-vue-next';
import { formatDistanceToNow } from 'date-fns';
import {
  getAllSystemSettings,
  getRecruitmentCampaignByProjectId,
  getRecruitmentMessageList,
  type CampaignDetailsResponse,
  type DistanceTierFilter,
  type GetAllSystemSettingsResponse,
  type GetEligibleContactsForProjectRecruitmentData,
  type GetRecruitmentMessageListResponse,
  type ProjectShortInfo,
  type StaffingContactSource,
} from '~/client';
import { Badge } from '~/components/ui/badge';
import { Button } from '~/components/ui/button';
import { Card } from '~/components/ui/card';
import { getCampaignUrgency } from '~/constants/recruitment/campaignUrgencyConfig';
import { getCampaignPauseReason } from '~/constants/recruitment/campaignPauseReasonConfig';
import { getChannelStrategy } from '~/constants/recruitment/channelStrategyConfig';
import { getDistanceClassification } from '~/constants/recruitment/distanceClassificationConfig';
import { getReadinessStage } from '~/constants/recruitment/readinessStageConfig';
import type { SelectableContact } from '~/components/recruitment/send/RecruitmentSendBatchDialog.vue';
import { Checkbox } from '~/components/ui/checkbox';
import { Alert, AlertTitle } from '~/components/ui/alert';
import { shouldClearSelectionOnNav } from '~/utils/recruitment/selectionNavReset';
import { exhaustionLabel } from '~/utils/recruitment/exhaustionLabel';

definePageMeta({
  roles: ['admin', 'manager'],
  backGroup: 'project-details',
  backLabel: 'project',
});

interface Props {
  projectId: string;
  projectShortInfo?: ProjectShortInfo;
}

const props = defineProps<Props>();

const route = useRoute();
const { isAdmin } = useUserRole();

const projectIdRef = computed(() => props.projectId);

type EligibleContactsQuery = NonNullable<GetEligibleContactsForProjectRecruitmentData['query']> & {
  page: number;
  size: number;
};

const params = computed((): EligibleContactsQuery => {
  const queryParams = {
    ...parsePagination(route.query, { size: 50 }),
    is_registered: parseBooleanQuery(route.query.is_registered as string),
    is_contacted: parseBooleanQuery(route.query.is_contacted as string),
    projects: processArrayQueryParameterFromUrl<string>(route.query.projects),
    background_check_complete: parseBooleanQuery(route.query.background_check_complete as string),
    source: processArrayQueryParameterFromUrl<StaffingContactSource>(route.query.source),
    top_canvasser: parseBooleanQuery(route.query.top_canvasser as string),
    top_petitioner: parseBooleanQuery(route.query.top_petitioner as string),
    total_projects_min: route.query.total_projects_min ? Number(route.query.total_projects_min) : undefined,
    total_projects_max: route.query.total_projects_max ? Number(route.query.total_projects_max) : undefined,
    search_query: (route.query.search_query as string) || undefined,
    distance_tiers: processArrayQueryParameterFromUrl<DistanceTierFilter>(route.query.distance_tiers),
  };

  return Object.fromEntries(
    Object.entries(queryParams).filter(([_, value]) => value !== undefined)
  ) as EligibleContactsQuery;
});

const { data, error, isLoading, refetch } = useProjectEligibleContacts(projectIdRef, params);

const tierTabs = computed<NavigationItem[]>(() => {
  const counts = data.value?.tier_counts;
  if (!counts) return [];
  return buildMultiSelectStatusTabs<DistanceTierFilter>({
    source: filteredDistanceTiersForTabs(),
    current: params.value.distance_tiers ?? [],
    allCount: counts.local + counts.qrf + counts.no_location,
    counts,
    buildTo: (next) => ({
      name: 'projects-id-recruitment',
      params: { id: props.projectId },
      query: { ...route.query, page: 1, distance_tiers: next.length ? next : undefined },
    }),
  });
});

const MAX_SELECTION = 50;
const selection = useCrossPageSelection<SelectableContact>((c) => c.email, MAX_SELECTION);

const selectableItems = computed<SelectableContact[]>(() =>
  (data.value?.items ?? []).map((c) => ({ email: c.email, first_name: c.first_name, last_name: c.last_name }))
);

const pageSelectState = computed(() => selection.pageSelectAllState(selectableItems.value));

const isSendDialogOpen = ref(false);

function onSent() {
  selection.clear();
  refetch();
}

const FILTER_KEYS = [
  'is_registered',
  'is_contacted',
  'projects',
  'background_check_complete',
  'source',
  'top_canvasser',
  'top_petitioner',
  'total_projects_min',
  'total_projects_max',
  'distance_tiers',
] as const;
// Router hook, not a watch: cross-page selection must survive page/size nav, so reset only when the
// FILTER_KEYS projection actually changes value.
onBeforeRouteUpdate((to, from) => {
  const next = FILTER_KEYS.map((k) => to.query[k]);
  const prev = FILTER_KEYS.map((k) => from.query[k]);
  if (shouldClearSelectionOnNav(next, prev)) selection.clear();
});

const { data: campaign, isLoading: isCampaignLoading } = useQuery({
  key: () => ['recruitment.campaign.by_project_id', props.projectId],
  query: (): Promise<CampaignDetailsResponse | null> =>
    getRecruitmentCampaignByProjectId({ composable: '$fetch', path: { project_id: props.projectId } }).catch((err) => {
      if (err?.statusCode === 404) return null;
      throw err;
    }),
});

const { data: settingsData, isLoading: isSettingsLoading } = useQuery({
  key: () => ['system-settings'],
  query: (): Promise<GetAllSystemSettingsResponse> => getAllSystemSettings({ composable: '$fetch' }),
});

// Both queries must settle before mounting: a campaign resolving to null is a valid answer, and the
// selector's prefill is captured once at mount.
const isDialogDataReady = computed(() => !isCampaignLoading.value && !isSettingsLoading.value);
const defaultChannelStrategy = computed(
  () => campaign.value?.channel_strategy ?? settingsData.value?.general_recruitment.channel_strategy
);
const defaultStrategySource = computed<'campaign' | 'general_settings'>(() =>
  campaign.value ? 'campaign' : 'general_settings'
);

// size: 1 - newest message only. Sort by created_at (always set); sent_at can be null.
const { data: messageActivity } = useQuery({
  key: () => ['recruitment.messages.activity.by_project_id', props.projectId],
  query: (): Promise<GetRecruitmentMessageListResponse> =>
    getRecruitmentMessageList({
      composable: '$fetch',
      query: { mentioned_project_ids: [props.projectId], page: 1, size: 1, sort_by: 'created_at', sort_type: 'desc' },
    }),
});

const messageCount = computed(() => messageActivity.value?.total_count ?? 0);
const latestMessageAt = computed(() => messageActivity.value?.items[0]?.created_at ?? null);
</script>
