import { getEligibleContactsForProjectRecruitment } from '~/client';
import type {
  GetEligibleContactsForProjectRecruitmentData,
  GetEligibleContactsForProjectRecruitmentResponse,
} from '~/client';

type Query = NonNullable<GetEligibleContactsForProjectRecruitmentData['query']>;

export function useProjectEligibleContacts(projectId: Ref<string>, params: Ref<Query>) {
  const { data, error, isLoading, refetch } = useQuery({
    key: () => ['project.recruitment.eligible_contacts', projectId.value, params.value],
    query: (): Promise<GetEligibleContactsForProjectRecruitmentResponse> =>
      getEligibleContactsForProjectRecruitment({
        composable: '$fetch',
        path: { project_id: projectId.value },
        query: ref(params.value),
      }),
    enabled: () => !!projectId.value,
    staleTime: 0,
  });
  return { data, error, isLoading, refetch };
}
