<template>
  <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-4">
    <AppSearchInputQuery
      :query="params.search_query || null"
      property-name="search_query"
      placeholder="Search contacts..."
    />
    <AppMultiComboboxQuery
      :value="params.projects || null"
      :items="projectItems"
      property-name="projects"
      :null-is-all="true"
      placeholder="All projects"
      items-plural-name="projects"
      empty-text="No projects found"
      :icon="BriefcaseIcon"
      :error="projectsError ? 'Failed to load list items' : null"
      :loading="projectsLoading"
      @open-change="onProjectsOpenChange"
    />
    <AppMultiComboboxQuery
      :value="params.source || null"
      :items="sourceOptions"
      property-name="source"
      :null-is-all="true"
      placeholder="All sources"
      items-plural-name="sources"
      empty-text="No sources found"
      :icon="ImportIcon"
    />
    <AppRangeNumberInputQuery
      :value="totalProjectsRange"
      :property-names="{ min: 'total_projects_min', max: 'total_projects_max' }"
      min-placeholder="Min projects"
      max-placeholder="Max projects"
      :icon="HashIcon"
      step="1"
    />
    <AppTriStateCheckboxQuery
      v-for="item in booleanFilters"
      :key="item.id"
      :value="item.value"
      :property-name="item.id"
      :label="item.label"
    />
  </div>
</template>

<script lang="ts" setup>
import { sourceOptions } from '~/constants/staffing-contacts/staffingContactSourceConfig';
import { getSelectorStaffingContactProjects, type GetEligibleContactsForProjectRecruitmentData } from '~/client';
import { BriefcaseIcon, HashIcon, ImportIcon } from 'lucide-vue-next';

const props = defineProps<{
  params: NonNullable<GetEligibleContactsForProjectRecruitmentData['query']>;
}>();

const {
  items: projectItems,
  error: projectsError,
  loading: projectsLoading,
  onOpenChange: onProjectsOpenChange,
} = useSelectorItems(
  ['project-recruitment.selector.projects'],
  () => getSelectorStaffingContactProjects({ composable: '$fetch' }),
  () => !!props.params.projects?.length
);

const totalProjectsRange = computed(() => ({
  min: props.params.total_projects_min ?? null,
  max: props.params.total_projects_max ?? null,
}));

const booleanFilters = computed(() => [
  { id: 'is_registered', label: 'Registered', value: props.params.is_registered },
  { id: 'is_contacted', label: 'Contacted', value: props.params.is_contacted },
  { id: 'top_canvasser', label: 'Top Canvasser', value: props.params.top_canvasser },
  { id: 'top_petitioner', label: 'Top Petitioner', value: props.params.top_petitioner },
  { id: 'background_check_complete', label: 'Background Check', value: props.params.background_check_complete },
]);
</script>
